 Example program code:
 Java
 public static String PopVowel(){
         String DataToReturn = "";
         if(VowelTop - 1 >= 0){
             VowelTop --;
             DataToReturn = StackVowel[VowelTop];
             return DataToReturn;
         }else{
             return "No data";
         }
     }
     public static String PopConsonant(){
         String DataToReturn = "";
         if(ConsonantTop - 1 >= 0){
             ConsonantTop--;
             DataToReturn = StackConsonant[ConsonantTop];
             return DataToReturn;
         }else{
             return "No data";
         }
     }
 VB.NET
     Function PopVowel()
         If VowelTop - 1 >= 0 Then
             VowelTop -= 1
             Dim DataToReturn As Char = StackVowel(VowelTop)
             Return DataToReturn
