             Return "No data"
         End If
     End Function
     Function PopConsonant()
         If ConsonantTop - 1 >= 0 Then
             ConsonantTop -= 1
             Dim DataToReturn As Char = StackConsonant(ConsonantTop)
             Return DataToReturn
         Else
             Return "No data"
         End If
     End Function
 Python
 def PopVowel():
     global VowelTop
     global ConsonantTop
     if VowelTop - 1 >= 0:
         VowelTop = VowelTop - 1
         DataToReturn = StackVowel[VowelTop]
         del StackVowel[-1]
         return DataToReturn
     else:
         return "No data"
 def PopConsonant():
     global VowelTop
     global ConsonantTop
     if ConsonantTop - 1 >= 0:
         ConsonantTop = ConsonantTop - 1
         DataToReturn = StackConsonant[ConsonantTop]
         del StackConsonant[-1]
         return DataToReturn
     else:
         return "No data"

