     public static Integer IterativeCalculate(Integer Number){
         Integer ToFind = Number;
         Integer Total = 0;
         while(Number != 0){
             if(ToFind % Number == 0){
                 Total += Number;
             }
             Number--;
         }
         return Total;
     }
 VB.NET
     Function IterativeCalculate(Number As Integer)
         Dim total As Integer = 0
         Dim ToFind As Integer = Number
         While Number <> 0
             If ToFind Mod Number = 0 Then
                 total = total + Number
             End If
             Number = Number - 1
         End While
         Return total
     End Function
