     public static Integer RecursiveValue(Integer Number, Integer ToFind){
         if(Number == 0){
             return 0;
         }else{
             if(ToFind % Number == 0){
                 return Number + RecursiveValue(Number - 1, ToFind);
             }else{
                 return RecursiveValue(Number - 1, ToFind);
             }
         }
     }
